<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import { askTutor } from '../store'
import { STUDY_DIRECTORY, type Mastery, type StudyBookDetail, type StudyCard, type StudyChapter, type StudyDifficulty, type StudyDocument } from '../types'
import RichText from '../components/RichText.vue'

type DirectoryEntry = { chapter: StudyChapter; depth: number; path: string[]; hasChildren: boolean }
const route = useRoute(); const router = useRouter()
const detail = ref<StudyBookDetail | null>(null); const loading = ref(true); const selectedId = ref<number | null>(null)
const collapsed = ref(new Set<number>()); const mobileDirectoryOpen = ref(false); const directoryDialog = ref(false); const editingDirectoryId = ref<number | null>(null)
const cardDialog = ref(false); const editingCardId = ref<number | null>(null); const saving = ref(false); const reciting = ref(false); const reciteIndex = ref(0); const revealed = ref(false)
const documentDialog = ref(false); const editingDocumentId = ref<number | null>(null); const aiImportDialog = ref(false); const parsing = ref(false); const aiText = ref('')
const directoryForm = reactive<{ title: string; parent_id: number | null }>({ title: '', parent_id: null })
const cardForm = reactive<{ chapter_id: number | null; question: string; summary: string; answer: string; followups: string; tags: string; difficulty: StudyDifficulty }>({ chapter_id: null, question: '', summary: '', answer: '', followups: '', tags: '', difficulty: '基础' })
const documentForm = reactive<{ chapter_id: number | null; title: string; summary: string; content: string; source_url: string; source_name: string }>({ chapter_id: null, title: '', summary: '', content: '', source_url: '', source_name: '' })
const chapterMap = computed(() => new Map((detail.value?.chapters ?? []).map(x => [x.id, x])))
const entries = computed<DirectoryEntry[]>(() => {
  const children = new Map<number | null, StudyChapter[]>(); for (const x of detail.value?.chapters ?? []) children.set(x.parent_id ?? null, [...(children.get(x.parent_id ?? null) ?? []), x])
  const result: DirectoryEntry[] = []; const visit = (parent: number | null, depth: number, path: string[]) => (children.get(parent) ?? []).sort((a,b) => a.sort-b.sort || a.id-b.id).forEach(x => { const next = [...path, x.title]; const hasChildren = Boolean(children.get(x.id)?.length); result.push({ chapter:x, depth, path:next, hasChildren }); if (!collapsed.value.has(x.id)) visit(x.id, depth+1, next) }); visit(null, 0, []); return result
})
const selected = computed(() => selectedId.value ? chapterMap.value.get(selectedId.value) ?? null : null)
const selectedEntry = computed(() => entries.value.find(x => x.chapter.id === selectedId.value) ?? null)
const editingDirectory = computed(() => editingDirectoryId.value ? chapterMap.value.get(editingDirectoryId.value) ?? null : null)
const allCards = computed(() => detail.value?.chapters.flatMap(x => x.cards) ?? []); const reciteCard = computed(() => allCards.value[reciteIndex.value] ?? null)
const directoryTitle = computed(() => detail.value ? STUDY_DIRECTORY.find(x => x.key === detail.value!.book.directory_key)?.title : '')
function pathFor(id: number): string[] { const result: string[] = []; const seen = new Set<number>(); let x = chapterMap.value.get(id); while (x && !seen.has(x.id)) { seen.add(x.id); result.unshift(x.title); x = x.parent_id ? chapterMap.value.get(x.parent_id) : undefined }; return result }
function contentCount(id: number): number { const current = chapterMap.value.get(id); if (!current) return 0; return current.cards.length + current.documents.length + [...chapterMap.value.values()].filter(item => item.parent_id === id).reduce((total, item) => total + contentCount(item.id), 0) }
function selectDirectory(id: number): void { selectedId.value=id; const next=new Set(collapsed.value); let x=chapterMap.value.get(id); while(x?.parent_id){next.delete(x.parent_id);x=chapterMap.value.get(x.parent_id)}; collapsed.value=next; mobileDirectoryOpen.value=false }
function toggle(id: number): void { const next=new Set(collapsed.value); next.has(id)?next.delete(id):next.add(id); collapsed.value=next }
async function load(): Promise<void> { loading.value=true; try { const next=await api.get<StudyBookDetail>(`/study/books/${route.params.id}`); detail.value=next; if (!selectedId.value || !next.chapters.some(x=>x.id===selectedId.value)) selectedId.value=next.chapters.find(x=>x.parent_id===null)?.id ?? next.chapters[0]?.id ?? null; if(selectedId.value) selectDirectory(selectedId.value); if(reciteIndex.value>=next.chapters.flatMap(x=>x.cards).length) reciteIndex.value=0 } catch(error){ElMessage.error((error as Error).message);void router.replace('/learn/study')} finally{loading.value=false} }
function openDirectory(parent?: StudyChapter, editing?: StudyChapter): void { editingDirectoryId.value=editing?.id??null; directoryForm.title=editing?.title??''; directoryForm.parent_id=editing ? editing.parent_id : parent?.id??null; directoryDialog.value=true }
async function saveDirectory(): Promise<void> { if(!detail.value||!directoryForm.title.trim()) return ElMessage.warning('请填写目录名称'); saving.value=true; try { if(editingDirectoryId.value){const updated=await api.put<StudyChapter>(`/study/chapters/${editingDirectoryId.value}`,directoryForm);const old=detail.value.chapters.find(x=>x.id===updated.id);if(old)Object.assign(old,updated);selectDirectory(updated.id)}else{const created=await api.post<StudyChapter>(`/study/books/${detail.value.book.id}/chapters`,directoryForm);detail.value.chapters.push({...created,cards:[],documents:[]});selectDirectory(created.id)};directoryDialog.value=false }catch(error){ElMessage.error((error as Error).message)}finally{saving.value=false} }
async function deleteDirectory(chapter: StudyChapter): Promise<void> { try{await ElMessageBox.confirm(`删除「${chapter.title}」会同时删除其下级目录和题目，确定继续吗？`,'删除目录',{type:'warning',confirmButtonText:'删除'});await api.delete(`/study/chapters/${chapter.id}`);await load();ElMessage.success('目录已删除')}catch{/* cancelled */} }
function openDocument(document?: StudyDocument): void { if(!detail.value?.chapters.length)return; editingDocumentId.value=document?.id??null; documentForm.chapter_id=document?.chapter_id??selectedId.value; documentForm.title=document?.title??''; documentForm.summary=document?.summary??''; documentForm.content=document?.content??''; documentForm.source_url=document?.source_url??''; documentForm.source_name=document?.source_name??''; documentDialog.value=true }
async function saveDocument(): Promise<void> { if(!documentForm.chapter_id||!documentForm.title.trim()||!detail.value)return ElMessage.warning('请填写文章标题');saving.value=true;try{if(editingDocumentId.value){const updated=await api.put<StudyDocument>(`/study/documents/${editingDocumentId.value}`,documentForm);detail.value.chapters.forEach(x=>x.documents=x.documents.filter(d=>d.id!==updated.id));detail.value.chapters.find(x=>x.id===updated.chapter_id)?.documents.push(updated)}else{const created=await api.post<StudyDocument>(`/study/chapters/${documentForm.chapter_id}/documents`,documentForm);detail.value.chapters.find(x=>x.id===created.chapter_id)?.documents.push(created)};documentDialog.value=false}catch(error){ElMessage.error((error as Error).message)}finally{saving.value=false} }
async function parseArticle(): Promise<void> { if(!detail.value||!selectedId.value||!aiText.value.trim())return ElMessage.warning('请先粘贴需要整理的资料'); parsing.value=true;try{const parsed=await api.post<{title:string;summary:string;content:string}>(`/study/books/${detail.value.book.id}/ai-parse`,{chapter_id:selectedId.value,text:aiText.value});documentForm.chapter_id=selectedId.value;documentForm.title=parsed.title;documentForm.summary=parsed.summary;documentForm.content=parsed.content;documentForm.source_url='';documentForm.source_name='';aiImportDialog.value=false;documentDialog.value=true;ElMessage.success('AI 已整理完成，请确认后保存')}catch(error){ElMessage.error((error as Error).message)}finally{parsing.value=false} }
async function deleteDocument(document:StudyDocument):Promise<void>{try{await ElMessageBox.confirm(`删除文章「${document.title}」？`,'删除文章',{type:'warning'});await api.delete(`/study/documents/${document.id}`);const parent=detail.value?.chapters.find(x=>x.id===document.chapter_id);if(parent)parent.documents=parent.documents.filter(x=>x.id!==document.id)}catch{/* cancelled */}}
async function deleteBook(): Promise<void> {
  if (!detail.value) return
  try {
    await ElMessageBox.confirm(`删除八股册「${detail.value.book.title}」会同时删除全部目录、题目和个人笔记，且无法恢复。`, '删除八股册', { type: 'warning', confirmButtonText: '删除八股册' })
    await api.delete(`/study/books/${detail.value.book.id}`)
    ElMessage.success('八股册已删除')
    await router.push('/learn/study')
  } catch { /* 取消 */ }
}
function openCard(card?: StudyCard): void { if(!detail.value?.chapters.length)return ElMessage.warning('请先新建一个目录');editingCardId.value=card?.id??null;cardForm.chapter_id=card?.chapter_id??selectedId.value??detail.value.chapters[0].id;cardForm.question=card?.question??'';cardForm.summary=card?.summary??'';cardForm.answer=card?.answer??'';cardForm.followups=card?.followups.join('\n')??'';cardForm.tags=card?.tags.join(', ')??'';cardForm.difficulty=card?.difficulty??'基础';cardDialog.value=true }
function payload():Record<string,unknown>{return{chapter_id:cardForm.chapter_id,question:cardForm.question,summary:cardForm.summary,answer:cardForm.answer,followups:cardForm.followups,tags:cardForm.tags,difficulty:cardForm.difficulty}}
async function saveCard(): Promise<void> { if(!detail.value||!cardForm.chapter_id||!cardForm.question.trim())return ElMessage.warning('请填写题目');saving.value=true;try{if(editingCardId.value){const updated=await api.put<StudyCard>(`/study/cards/${editingCardId.value}`,payload());let previous:StudyCard|undefined;detail.value.chapters.forEach(x=>{const i=x.cards.findIndex(c=>c.id===updated.id);if(i>=0)previous=x.cards.splice(i,1)[0]});detail.value.chapters.find(x=>x.id===updated.chapter_id)?.cards.push({...previous,...updated}as StudyCard)}else{const created=await api.post<StudyCard>(`/study/chapters/${cardForm.chapter_id}/cards`,payload());detail.value.chapters.find(x=>x.id===created.chapter_id)?.cards.push(created)};cardDialog.value=false}catch(error){ElMessage.error((error as Error).message)}finally{saving.value=false} }
async function deleteCard(card:StudyCard):Promise<void>{try{await ElMessageBox.confirm(`删除「${card.question}」？`,'删除题目',{type:'warning'});await api.delete(`/study/cards/${card.id}`);const chapter=detail.value?.chapters.find(x=>x.id===card.chapter_id);if(chapter)chapter.cards=chapter.cards.filter(x=>x.id!==card.id)}catch{/* cancelled */}}
async function progress(card:StudyCard, familiarity:Mastery=card.familiarity):Promise<void>{try{const result=await api.put<{familiarity:Mastery;note:string}>(`/study/cards/${card.id}/progress`,{familiarity,note:card.note});card.familiarity=result.familiarity;card.note=result.note}catch(error){ElMessage.error((error as Error).message)}}
function beginRecite():void{if(!allCards.value.length)return ElMessage.warning('先添加题目，才能开始背诵');reciteIndex.value=0;revealed.value=false;reciting.value=true} function next(step:number):void{reciteIndex.value=(reciteIndex.value+step+allCards.value.length)%allCards.value.length;revealed.value=false}
watch(()=>route.params.id,load);onMounted(load)
</script>

<template>
  <section v-loading="loading" class="study-reader" v-if="detail">
    <header class="reader-hero"><div><el-button text class="back" @click="router.push('/learn/study')">‹ 八股文</el-button><p class="kicker">{{ directoryTitle }}</p><h1>{{ detail.book.title }}</h1><p>{{ detail.book.description || '按目录阅读、背诵并记录自己的理解。' }}</p></div><div class="reader-actions"><el-tag effect="plain">{{ detail.book.visibility==='public'?'公共八股册':'我的八股册' }}</el-tag><el-button v-if="detail.book.can_edit" plain type="danger" @click="deleteBook">删除八股册</el-button><el-button type="primary" :disabled="!allCards.length" @click="beginRecite">背诵模式</el-button></div></header>
    <button class="mobile-directory" type="button" @click="mobileDirectoryOpen=true"><span>{{ selectedEntry?.path.join(' ＞ ') || '选择目录' }}</span><b>目录 ›</b></button>
    <div class="reader-layout"><aside class="reader-directory"><div class="directory-head"><b>目录</b><el-button v-if="detail.book.can_edit" link type="primary" @click="openDirectory()">＋ 目录</el-button></div><div class="tree"><div v-for="entry in entries" :key="entry.chapter.id" class="node" :class="{active:selectedId===entry.chapter.id}" :style="{ '--depth':entry.depth }"><button v-if="entry.hasChildren" class="toggle" @click="toggle(entry.chapter.id)">{{collapsed.has(entry.chapter.id)?'›':'⌄'}}</button><i v-else /><button class="node-name" @click="selectDirectory(entry.chapter.id)"><b>{{entry.chapter.title}}</b><small>{{contentCount(entry.chapter.id)}}</small></button><span v-if="detail.book.can_edit" class="node-tools"><button title="子目录" @click="openDirectory(entry.chapter)">＋</button><button title="编辑目录" @click="openDirectory(undefined,entry.chapter)">···</button></span></div></div><el-empty v-if="!entries.length" description="还没有目录" :image-size="55" /></aside>
      <main class="reader-content"><template v-if="selected"><div class="chapter-head"><div><p class="kicker">{{selectedEntry?.path.join(' ＞ ')}}</p><h2>{{selected.title}}</h2><span>{{selected.documents.length}} 篇文章 · {{selected.cards.length}} 道题目</span></div><div v-if="detail.book.can_edit" class="chapter-actions"><el-button plain @click="openDirectory(selected)">＋ 子目录</el-button><el-button plain @click="aiImportDialog=true">AI 解析原文</el-button><el-button plain @click="openDocument()">＋ 文章</el-button><el-button type="primary" @click="openCard()">＋ 题目</el-button></div></div><el-empty v-if="!selected.documents.length&&!selected.cards.length" description="这个目录下还没有内容"><div v-if="detail.book.can_edit"><el-button @click="openDirectory(selected)">新建子目录</el-button><el-button type="primary" @click="aiImportDialog=true">AI 解析原文</el-button></div></el-empty><article v-for="document in selected.documents" :key="document.id" class="study-document"><div class="document-meta"><span v-if="document.source_name">{{document.source_name}}</span><a v-if="document.source_url" :href="document.source_url" target="_blank" rel="noreferrer">查看来源 ↗</a><span v-if="detail.book.can_edit"><el-button link size="small" @click="openDocument(document)">编辑</el-button><el-button link type="danger" size="small" @click="deleteDocument(document)">删除</el-button></span></div><h2>{{document.title}}</h2><p v-if="document.summary" class="document-summary">{{document.summary}}</p><RichText :content="document.content" /></article><article v-for="(card,index) in selected.cards" :key="card.id" class="study-card"><div class="card-top"><span>练习题 {{index+1}}</span><div><el-tag size="small">{{card.difficulty}}</el-tag><el-tag v-for="tag in card.tags" :key="tag" size="small">{{tag}}</el-tag></div></div><h3>{{card.question}}</h3><p v-if="card.summary" class="summary">{{card.summary}}</p><div class="answer"><RichText v-if="card.answer" :content="card.answer" /><span v-else>暂未填写详细答案</span></div><div class="card-bottom"><div class="mastery"><span>掌握情况</span><button v-for="item in [{value:0,label:'不熟'},{value:1,label:'一般'},{value:2,label:'熟悉'}]" :key="item.value" :class="{active:card.familiarity===item.value}" @click="progress(card,item.value as Mastery)">{{item.label}}</button></div><div><el-button link type="primary" size="small" @click="askTutor(card.question)">问 AI</el-button><el-button v-if="detail.book.can_edit" link size="small" @click="openCard(card)">编辑</el-button><el-button v-if="detail.book.can_edit" link type="danger" size="small" @click="deleteCard(card)">删除</el-button></div></div><el-input v-model="card.note" type="textarea" :rows="2" placeholder="我的笔记" @blur="progress(card)" /></article></template><el-empty v-else description="先创建一个顶层目录"><el-button v-if="detail.book.can_edit" type="primary" @click="openDirectory()">新建目录</el-button></el-empty></main></div>
  </section>
  <el-drawer v-model="mobileDirectoryOpen" title="目录" direction="ltr" size="88%" class="study-directory-drawer" append-to-body><div class="tree"><div v-for="entry in entries" :key="entry.chapter.id" class="node" :class="{active:selectedId===entry.chapter.id}" :style="{ '--depth':entry.depth }"><button v-if="entry.hasChildren" class="toggle" @click="toggle(entry.chapter.id)">{{collapsed.has(entry.chapter.id)?'›':'⌄'}}</button><i v-else /><button class="node-name" @click="selectDirectory(entry.chapter.id)"><b>{{entry.chapter.title}}</b><small>{{contentCount(entry.chapter.id)}}</small></button></div></div></el-drawer>
  <el-dialog v-model="directoryDialog" :title="editingDirectoryId?'编辑目录':'新建目录'" width="460px" class="study-editor-dialog" append-to-body><el-form label-position="top"><el-form-item label="目录名称" required><el-input v-model="directoryForm.title" maxlength="160" @keyup.enter="saveDirectory" /></el-form-item><el-form-item label="上级目录"><el-select v-model="directoryForm.parent_id" clearable placeholder="不选则作为顶层目录" style="width:100%"><el-option v-for="entry in entries" :key="entry.chapter.id" :value="entry.chapter.id" :disabled="entry.chapter.id===editingDirectoryId" :label="`${'　'.repeat(entry.depth)}${entry.chapter.title}`" /></el-select></el-form-item></el-form><template #footer><el-button v-if="editingDirectory" type="danger" plain @click="deleteDirectory(editingDirectory)">删除目录</el-button><el-button @click="directoryDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDirectory">保存</el-button></template></el-dialog>
  <el-dialog v-model="cardDialog" :title="editingCardId?'编辑题目':'添加题目'" width="760px" class="study-editor-dialog" append-to-body><el-form label-position="top"><el-form-item label="所属目录" required><el-select v-model="cardForm.chapter_id" style="width:100%"><el-option v-for="entry in entries" :key="entry.chapter.id" :value="entry.chapter.id" :label="`${'　'.repeat(entry.depth)}${entry.chapter.title}`" /></el-select></el-form-item><el-form-item label="问题" required><el-input v-model="cardForm.question" type="textarea" :rows="2" /></el-form-item><el-form-item label="一句话答案"><el-input v-model="cardForm.summary" type="textarea" :rows="2" /></el-form-item><el-form-item label="详细答案（支持 Markdown）"><el-input v-model="cardForm.answer" type="textarea" :rows="9" /></el-form-item><div class="form-grid"><el-form-item label="常见追问（一行一个）"><el-input v-model="cardForm.followups" type="textarea" :rows="3" /></el-form-item><el-form-item label="标签（逗号或换行分隔）"><el-input v-model="cardForm.tags" type="textarea" :rows="3" /></el-form-item></div><el-form-item label="难度"><el-radio-group v-model="cardForm.difficulty"><el-radio-button value="基础">基础</el-radio-button><el-radio-button value="进阶">进阶</el-radio-button><el-radio-button value="深入">深入</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="cardDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCard">保存题目</el-button></template></el-dialog>
  <el-dialog v-model="documentDialog" :title="editingDocumentId?'编辑文章':'新增文章'" width="760px" class="study-editor-dialog" append-to-body><el-form label-position="top"><el-form-item label="所属目录" required><el-select v-model="documentForm.chapter_id" style="width:100%"><el-option v-for="entry in entries" :key="entry.chapter.id" :value="entry.chapter.id" :label="`${'　'.repeat(entry.depth)}${entry.chapter.title}`" /></el-select></el-form-item><el-form-item label="文章标题" required><el-input v-model="documentForm.title" /></el-form-item><el-form-item label="摘要"><el-input v-model="documentForm.summary" type="textarea" :rows="2" /></el-form-item><el-form-item label="正文（支持 Markdown）"><el-input v-model="documentForm.content" type="textarea" :rows="12" /></el-form-item><div class="form-grid"><el-form-item label="来源名称（可选）"><el-input v-model="documentForm.source_name" /></el-form-item><el-form-item label="来源链接（可选）"><el-input v-model="documentForm.source_url" /></el-form-item></div></el-form><template #footer><el-button @click="documentDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDocument">保存文章</el-button></template></el-dialog>
  <el-dialog v-model="aiImportDialog" title="AI 解析学习资料" width="700px" class="study-editor-dialog" append-to-body><p class="import-note">粘贴你有权使用的原文，AI 会整理成一篇 Markdown 文章。单次最多 2 万字，长资料请按章节分段处理；生成后请检查并确认再保存。</p><el-input v-model="aiText" type="textarea" :rows="14" maxlength="20000" show-word-limit placeholder="粘贴文章、笔记或课程资料正文" /><template #footer><el-button @click="aiImportDialog=false">取消</el-button><el-button type="primary" :loading="parsing" @click="parseArticle">开始解析</el-button></template></el-dialog>
  <el-dialog v-model="reciting" width="680px" class="study-recite-dialog" append-to-body><template #header><div class="recite-head"><span>背诵模式</span><small>{{reciteIndex+1}} / {{allCards.length}}</small></div></template><template v-if="reciteCard"><p class="kicker">{{pathFor(reciteCard.chapter_id).join(' ＞ ')}}</p><h2>{{reciteCard.question}}</h2><p v-if="reciteCard.summary">提示：{{reciteCard.summary}}</p><el-button v-if="!revealed" type="primary" plain class="reveal" @click="revealed=true">我想好了，显示答案</el-button><div v-else class="recite-answer"><RichText :content="reciteCard.answer||'暂未填写详细答案'" /></div><footer><el-button @click="next(-1)">‹ 上一题</el-button><el-button type="primary" @click="next(1)">下一题 ›</el-button></footer></template></el-dialog>
</template>

